Here's how to handle each scenario with modern MSTest (3.9+/3.10+) attributes:

```csharp
[TestClass]
public sealed class AdvancedScenarioTests : IDisposable
{
    private readonly TestContext _testContext;
    private string? _tempFilePath;

    public AdvancedScenarioTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void ReadRegistry_OnWindows_ReturnsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Setting", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void RenderFrame_WithLocalGpu_ProducesOutput()
    {
        var result = GpuRenderer.RenderFrame();
        Assert.IsNotEmpty(result.Pixels);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task GetWeather_ExternalApi_ReturnsData()
    {
        var weather = await WeatherClient.GetCurrentAsync(
            "Seattle", _testContext.CancellationToken);
        Assert.IsNotNull(weather);
    }

    // 4. Temp file cleanup — TestCleanup runs even on failure
    [TestMethod]
    public void ExportReport_WritesToTempFile()
    {
        _tempFilePath = Path.Combine(Path.GetTempPath(), $"{Guid.NewGuid()}.csv");

        ReportService.Export(_tempFilePath);

        Assert.IsNotEmpty(File.ReadAllLines(_tempFilePath));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFilePath is not null && File.Exists(_tempFilePath))
        {
            File.Delete(_tempFilePath);
        }
    }

    public void Dispose()
    {
        // Fallback safety net for cleanup
        Cleanup();
    }
}
```

**Summary of attributes used:**

| Scenario | Solution |
|----------|----------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` — skips on Linux/macOS |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` — runs only locally |
| Flaky API | `[Retry(3)]` — retries up to 3 times before failing |
| Temp file cleanup | `[TestCleanup]` — always runs, even on test failure |

**Key notes:**
- `[Retry]` requires MSTest 3.9+; `[OSCondition]`/`[CICondition]` require 3.10+
- Combine `[Timeout]` with `TestContext.CancellationToken` for cooperative cancellation
- `[TestCleanup]` is preferred over `Dispose` for test-aware cleanup (it has access to `TestContext`), but implementing `IDisposable` adds a safety net
